def ensure_placeholder_assets(paper_id: str, sheet_id: str):
    """Ensure sample question paper image and sheet page images exist on disk."""
    try:
        from PIL import Image, ImageDraw
    except ImportError:
        Image, ImageDraw = None, None

    paper_dir = PAPERS_STORAGE_DIR / paper_id
    paper_dir.mkdir(parents=True, exist_ok=True)
    paper_img = paper_dir / "question_paper_Linux.jpeg"
    if not paper_img.exists() and Image:
        im = Image.new("RGB", (1200, 1600), color=(250, 250, 248))
        d = ImageDraw.Draw(im)
        d.text((80, 80), "B.C.A. II Sem Examination - Linux Architecture & Administration", fill=(30, 40, 50))
        d.text((80, 120), "Total Marks: 60  |  Time: 3 Hours  |  Code: CS-202", fill=(80, 90, 100))
        d.line([(80, 150), (1120, 150)], fill=(120, 130, 140), width=2)
        im.save(paper_img, "JPEG", quality=90)

    sheet_dir = SHEETS_STORAGE_DIR / sheet_id / "original"
    sheet_dir.mkdir(parents=True, exist_ok=True)
    for p_num in range(1, 10):
        p_path = sheet_dir / f"page_{p_num:02d}.jpg"
        if not p_path.exists() and Image:
            im = Image.new("RGB", (1200, 1600), color=(255, 255, 255))
            d = ImageDraw.Draw(im)
            d.text((60, 60), f"EvalDesk Verified Answer Sheet — Candidate: Kanak Patel (SGSU250489)", fill=(40, 50, 60))
            d.text((60, 90), f"Page {p_num} of 9  |  Paper: Linux Architecture & Administration", fill=(90, 100, 110))
            d.line([(60, 120), (1140, 120)], fill=(180, 190, 200), width=1)
            d.text((80, 160), f"[Handwritten response section - Page {p_num}]", fill=(120, 130, 140))
            im.save(p_path, "JPEG", quality=85)


def seed_canonical_cohort(target_db: Optional[Path] = None) -> bool:
    """Populates the canonical Linux paper and student cohort into target SQLite database."""
    target_path = Path(target_db) if target_db else DB_PATH
    target_path.parent.mkdir(parents=True, exist_ok=True)

    conn = sqlite3.connect(str(target_path))
    cur = conn.cursor()

    paper_id = PAPER_DATA["id"]

    # 1. Insert Paper
    cur.execute("""
        INSERT OR REPLACE INTO papers (
            id, title, subject, total_marks, strictness, checking_medium,
            has_answer_key, is_locked, instructions, paper_path, answer_key_path,
            created_at, updated_at, subject_code, exam_name, strictness_level,
            subject_domain, class_name
        ) VALUES (
            :id, :title, :subject, :total_marks, :strictness, :checking_medium,
            :has_answer_key, :is_locked, :instructions, :paper_path, :answer_key_path,
            :created_at, :updated_at, :subject_code, :exam_name, :strictness_level,
            :subject_domain, :class_name
        )
    """, PAPER_DATA)

    # 2. Insert Sections
    for sec in SECTIONS_DATA:
        cur.execute("""
            INSERT OR REPLACE INTO sections (
                id, paper_id, name, instructions, attempt_n, total_questions,
                marks_each, section_marks, policy
            ) VALUES (
                :id, :paper_id, :name, :instructions, :attempt_n, :total_questions,
                :marks_each, :section_marks, :policy
            )
        """, sec)

    # 3. Insert Questions
    for q in QUESTIONS_DATA:
        cur.execute("""
            INSERT OR REPLACE INTO questions (
                id, paper_id, key, q_no, question_text, max_marks, question_type,
                section_name, options_json, word_limit, strictness_override,
                checking_medium_override, order_idx, section_id, strictness_level_override
            ) VALUES (
                :id, :paper_id, :key, :q_no, :question_text, :max_marks, :question_type,
                :section_name, :options_json, :word_limit, :strictness_override,
                :checking_medium_override, :order_idx, :section_id, :strictness_level_override
            )
        """, q)

    # 4. Insert References
    for ref in REFERENCES_DATA:
        cur.execute("""
            INSERT OR REPLACE INTO "references" (
                id, paper_id, question_id, key, source, model_answer, key_points_json,
                correct_option, is_approved, approved_by, approved_at
            ) VALUES (
                :id, :paper_id, :question_id, :key, :source, :model_answer, :key_points_json,
                :correct_option, :is_approved, :approved_by, :approved_at
            )
        """, ref)

    # 5. Insert Primary Candidate: Kanak Patel
    cur.execute("""
        INSERT OR REPLACE INTO sheets (
            id, paper_id, student_name, roll_number, class_name, consent_flag,
            status, stage_key, raw_filename, current_stage, error_message,
            total_score, max_marks, percentage, grade, created_at, updated_at
        ) VALUES (
            :id, :paper_id, :student_name, :roll_number, :class_name, :consent_flag,
            :status, :stage_key, :raw_filename, :current_stage, :error_message,
            :total_score, :max_marks, :percentage, :grade, :created_at, :updated_at
        )
    """, KANAK_SHEET)

    for sp in KANAK_PAGES:
        cur.execute("""
            INSERT OR REPLACE INTO sheet_pages (
                id, sheet_id, page_number, file_path, ocr_status, ocr_error,
                ocr_legibility, finished_at
            ) VALUES (
                :id, :sheet_id, :page_number, :file_path, :ocr_status, :ocr_error,
                :ocr_legibility, :finished_at
            )
        """, sp)

    for ans in KANAK_ANSWERS:
        cur.execute("""
            INSERT OR REPLACE INTO answers (
                id, sheet_id, question_id, extracted_text, region_box_json,
                legibility_score, is_attempted, page_number
            ) VALUES (
                :id, :sheet_id, :question_id, :extracted_text, :region_box_json,
                :legibility_score, :is_attempted, :page_number
            )
        """, ans)

    for ev in KANAK_EVALS:
        cur.execute("""
            INSERT OR REPLACE INTO evaluations (
                id, sheet_id, question_id, ai_marks, final_marks, reason,
                evidence_quote, confidence, flags_json, evaluation_basis,
                resolved, strictness_used, verdicts_json, status, is_counted
            ) VALUES (
                :id, :sheet_id, :question_id, :ai_marks, :final_marks, :reason,
                :evidence_quote, :confidence, :flags_json, :evaluation_basis,
                :resolved, :strictness_used, :verdicts_json, :status, :is_counted
            )
        """, ev)

    # 6. Insert Cohort Candidates
    q_map = {q["id"]: q for q in QUESTIONS_DATA}
    for cand in COHORT_STUDENTS:
        cur.execute("""
            INSERT OR REPLACE INTO sheets (
                id, paper_id, student_name, roll_number, class_name, consent_flag,
                status, stage_key, raw_filename, current_stage, total_score,
                max_marks, percentage, grade, created_at, updated_at
            ) VALUES (
                ?, ?, ?, ?, 'CS-A', 1, ?, 'needs_review', 'cohort_scan.pdf',
                'Finalized', ?, ?, ?, ?, datetime('now'), datetime('now')
            )
        """, (
            cand["id"], paper_id, cand["student_name"], cand["roll_number"],
            cand["status"], cand["total_score"], cand["max_marks"],
            cand["percentage"], cand["grade"]
        ))

        # Answers & evaluations for cohort candidate
        mult = cand["multiplier"]
        for idx, base_ev in enumerate(KANAK_EVALS):
            qid = base_ev["question_id"]
            q_info = q_map.get(qid, {"max_marks": 1.0})
            max_m = float(q_info["max_marks"])
            base_score = float(base_ev["final_marks"])
            scaled_score = min(max_m, round(base_score * mult * 2) / 2.0)
            c_eid = f"{cand['id'][:8]}-ev-{idx:02d}"
            c_aid = f"{cand['id'][:8]}-ans-{idx:02d}"

            cur.execute("""
                INSERT OR REPLACE INTO answers (
                    id, sheet_id, question_id, extracted_text, region_box_json,
                    legibility_score, is_attempted, page_number
                ) VALUES (
                    ?, ?, ?, 'Candidate response text for evaluation audit.', '{}',
                    0.92, 1, 1
                )
            """, (c_aid, cand["id"], qid))

            cur.execute("""
                INSERT OR REPLACE INTO evaluations (
                    id, sheet_id, question_id, ai_marks, final_marks, reason,
                    evidence_quote, confidence, flags_json, evaluation_basis,
                    resolved, strictness_used, verdicts_json, status, is_counted
                ) VALUES (
                    ?, ?, ?, ?, ?, 'Evaluated in cohort batch processing.',
                    '', 0.90, '[]', 'ai_reference', 1, 3, '[]', 'ok', 1
                )
            """, (c_eid, cand["id"], qid, scaled_score, scaled_score))

    conn.commit()
    conn.close()

    # Ensure assets and dual database sync
    ensure_placeholder_assets(paper_id, KANAK_SHEET["id"])

    # Synchronize between evaldesk.db (root) and data/app.db
    app_db = DATA_DIR / "app.db"
    evaldesk_db = BASE_DIR / "evaldesk.db"
    try:
        if target_path == evaldesk_db and target_path.exists():
            DATA_DIR.mkdir(parents=True, exist_ok=True)
            shutil.copy2(target_path, app_db)
        elif target_path == app_db and target_path.exists():
            shutil.copy2(target_path, evaldesk_db)
    except Exception as e:
        print(f"[Canonical Seed] DB mirror sync note: {e}")

    print(f"[Canonical Seed] Successfully seeded paper '{PAPER_DATA['title']}' and cohort of {len(COHORT_STUDENTS) + 1} students into {target_path}")
    return True


def seed_canonical_cohort_if_empty(target_db: Optional[Path] = None) -> bool:
    """Checks if the database has any papers/sheets, and seeds the canonical cohort if empty."""
    target_path = Path(target_db) if target_db else DB_PATH
    if not target_path.exists():
        from backend.db import init_db
        init_db()

    conn = sqlite3.connect(str(target_path))
    cur = conn.cursor()
    try:
        cur.execute("SELECT COUNT(*) FROM papers")
        paper_count = cur.fetchone()[0]
        cur.execute("SELECT COUNT(*) FROM sheets")
        sheet_count = cur.fetchone()[0]
    except sqlite3.OperationalError:
        paper_count = 0
        sheet_count = 0
    finally:
        conn.close()

    if paper_count == 0 or sheet_count == 0:
        print(f"[Canonical Seed] Database {target_path} is empty (papers={paper_count}, sheets={sheet_count}). Seeding canonical Linux cohort...")
        return seed_canonical_cohort(target_path)
    return False

if __name__ == "__main__":
    seed_canonical_cohort_if_empty()
